-- S8.3 Discover V2 completion (ADR-016, ADR-017): operator-recorded
-- Acquisition Channels with evidence, primacy and confidence; rights-gated
-- private visuals with removal and revalidation; least_analyzed sort.
-- Synthetic fixtures only (.test hosts, generated bytes).
begin;
select no_plan();
select tests.seed();

-- ------------------------------------------------------------ privileges
select ok((select relrowsecurity from pg_class where oid = 'public.product_visual_asset_files'::regclass),
  'the private copies table has RLS enabled');
select ok(not has_table_privilege('authenticated', 'public.product_visual_asset_files', 'SELECT')
          and not has_table_privilege('anon', 'public.product_visual_asset_files', 'SELECT'),
  'browsers cannot read private copies directly');
select ok(not has_function_privilege('authenticated', 'public.sor_operator_record_acquisition_channel(uuid,uuid,jsonb)', 'EXECUTE')
          and not has_function_privilege('authenticated', 'public.sor_operator_retract_acquisition_channel(uuid,uuid,text)', 'EXECUTE')
          and not has_function_privilege('authenticated', 'public.sor_admit_visual_asset(uuid,uuid,jsonb,bytea)', 'EXECUTE')
          and not has_function_privilege('authenticated', 'public.sor_operator_remove_visual_asset(uuid,uuid,text)', 'EXECUTE')
          and not has_function_privilege('authenticated', 'public.sor_record_visual_asset_check(uuid,text,text)', 'EXECUTE')
          and not has_function_privilege('anon', 'public.sor_admit_visual_asset(uuid,uuid,jsonb,bytea)', 'EXECUTE'),
  'browsers cannot record channels or admit, remove or check visuals');
select ok(has_function_privilege('service_role', 'public.sor_operator_record_acquisition_channel(uuid,uuid,jsonb)', 'EXECUTE')
          and has_function_privilege('service_role', 'public.sor_admit_visual_asset(uuid,uuid,jsonb,bytea)', 'EXECUTE'),
  'the server records channels and admits visuals');

-- ------------------------------------------------------------ fixtures
insert into public.platform_operators (user_id, note) values (tests.id('a1'), 'product owner (PD-12)');
create temporary table r (k text primary key, v jsonb) on commit drop;
grant all on r to service_role, authenticated;
create function tests.channel(p_key text, p_category text, p_role text, p_status text, p_kind text,
                              p_verified boolean, p_extra jsonb default '{}'::jsonb)
returns jsonb language sql set search_path = '' as $$
  select jsonb_build_object('channel_key', p_key, 'channel_category', p_category, 'role', p_role,
    'status', p_status, 'evidence_kind', p_kind, 'verified', p_verified,
    'source_url', 'https://product-one.test/blog/how-we-grew', 'excerpt', 'We grow mostly through ' || p_key,
    'observed_at', '2026-11-01T00:00:00Z', 'confidence', 70, 'confidence_method', 'chanconf-1',
    'confidence_reasons', jsonb_build_array('Statut déclaré (base 60)')) || p_extra
$$;
-- Synthetic PNG header (1600x700) padded: not a real product visual.
create function tests.png() returns bytea language sql set search_path = '' as $$
  select '\x89504e470d0a1a0a0000000d49484452000006400000002b'::bytea || pg_catalog.convert_to(repeat('x', 64), 'UTF8')
$$;
create function tests.asset(p_extra jsonb default '{}'::jsonb) returns jsonb language sql set search_path = '' as $$
  select jsonb_build_object('asset_type', 'official_hero', 'image_url', 'https://product-one.test/hero.png',
    'page_url', 'https://product-one.test/press', 'alt_text', 'Tableau de bord de Product One',
    'rights_basis', 'Press kit: reuse and storage allowed with attribution (synthetic test case)',
    'rights_evidence_url', 'https://product-one.test/press/licence', 'covers_private_copy', true,
    'content_type', 'image/png', 'width', 1600, 'height', 700, 'primary', true) || p_extra
$$;
grant execute on all functions in schema tests to service_role, authenticated;
select tests.as_service_role();

-- ------------------------------------------------------------ channels: refusals
select throws_ok($$select public.sor_operator_record_acquisition_channel(tests.id('a3'), tests.id('d1'),
    tests.channel('reddit','community','secondary','declared','official_statement',true))$$,
  '42501', null, 'only a platform operator records a channel');
select throws_ok($$select public.sor_operator_record_acquisition_channel(tests.id('a1'), tests.id('d3'),
    tests.channel('reddit','community','secondary','declared','official_statement',true))$$,
  '22023', null, 'no channel on a product that is not visible (excluded)');
select throws_ok($$select public.sor_operator_record_acquisition_channel(tests.id('a1'), tests.id('d1'),
    tests.channel('unknown','community','secondary','declared','official_statement',true))$$,
  '22023', null, 'unknown is never recorded as a channel');
select throws_ok($$select public.sor_operator_record_acquisition_channel(tests.id('a1'), tests.id('d1'),
    tests.channel('reddit','community','secondary','confirmed','official_statement',false))$$,
  '22023', null, 'a confirmed channel needs verified evidence');
select throws_ok($$select public.sor_operator_record_acquisition_channel(tests.id('a1'), tests.id('d1'),
    tests.channel('reddit','community','secondary','estimated','inference',false))$$,
  '22023', null, 'an estimate needs its method and indices');
select throws_ok($$select public.sor_operator_record_acquisition_channel(tests.id('a1'), tests.id('d1'),
    tests.channel('reddit','community','primary','declared','official_statement',true))$$,
  '22023', null, 'a primary channel needs evidence of primacy');
select throws_ok($$select public.sor_operator_record_acquisition_channel(tests.id('a1'), tests.id('d1'),
    tests.channel('reddit','community','secondary','declared','official_statement',true,
                  '{"source_url":"http://product-one.test/"}'))$$,
  '22023', null, 'the cited source must be an https URL');

-- ------------------------------------------------------------ channels: record
insert into r values ('reddit', to_jsonb(public.sor_operator_record_acquisition_channel(tests.id('a1'), tests.id('d1'),
  tests.channel('reddit','community','primary','declared','official_statement',true,
                '{"role_rationale":"Most of our customers find us on Reddit"}'))));
select is((select e.claim_type::text || '/' || e.fact_status::text || '/' || e.verification_status::text || '/' || s.source_key
             from public.product_acquisition_channels c
             join public.evidence_items e on e.id = c.evidence_id
             join public.source_snapshots ss on ss.id = e.source_snapshot_id
             join public.source_records sr on sr.id = ss.source_record_id
             join public.sources s on s.id = sr.source_id
            where c.id = (select (v #>> '{}')::uuid from r where k = 'reddit')),
  'acquisition_channel/declared/verified/manual_entry',
  'the channel cites evidence of the product, from the page the operator cited');
select throws_ok($$select public.sor_operator_record_acquisition_channel(tests.id('a1'), tests.id('d1'),
    tests.channel('seo','content_search','primary','declared','official_statement',true,
                  '{"role_rationale":"SEO is our main channel"}'))$$,
  '55000', null, 'one primary channel at a time');
insert into r values ('seo', to_jsonb(public.sor_operator_record_acquisition_channel(tests.id('a1'), tests.id('d1'),
  tests.channel('seo','content_search','secondary','estimated','inference',false,
                '{"rationale":"Many ranking blog articles link to the trial","confidence":30}'))));
insert into r values ('reddit2', to_jsonb(public.sor_operator_record_acquisition_channel(tests.id('a1'), tests.id('d1'),
  tests.channel('reddit','community','primary','declared','official_statement',true,
                '{"role_rationale":"Most of our customers find us on Reddit","confidence":75}'))));
select is((select count(*)::int from public.product_acquisition_channels
            where product_id = tests.id('d1') and channel_key = 'reddit' and is_current), 1,
  'recording a channel again supersedes the previous claim (history kept)');
select is((select count(*)::int from public.product_acquisition_channels
            where product_id = tests.id('d1') and channel_key = 'reddit'), 2,
  'the superseded claim stays in history');

select tests.authenticate_as(tests.id('a4'));
select is((select jsonb_agg(c ->> 'channel_key' || ':' || (c ->> 'role') || ':' || (c ->> 'status'))
             from public.catalog_discover_metadata(array[tests.id('d1')]) m,
                  jsonb_array_elements(m.acquisition_channels) c),
  '["reddit:primary:declared", "seo:secondary:estimated"]'::jsonb,
  'Discover shows current channels, primary first, with their status');
select is((select (c -> 'confidence_reasons') ->> 0 from public.catalog_discover_metadata(array[tests.id('d1')]) m,
                  jsonb_array_elements(m.acquisition_channels) c where c ->> 'channel_key' = 'reddit'),
  'Statut déclaré (base 60)', 'the confidence comes with its reasons');
select ok(private.catalog_channel_matches(tests.id('d1'), '{"values":["seo"],"statuses":["estimated"],"include_unknown":false}'),
  'the channel filter matches the recorded key and status');

-- ------------------------------------------------------------ channels: retract
select tests.as_service_role();
select throws_ok(format($$select public.sor_operator_retract_acquisition_channel(%L, %L, '  ')$$,
                        tests.id('a1'), (select v #>> '{}' from r where k = 'seo')),
  '22023', null, 'a retraction needs a reason');
select lives_ok(format($$select public.sor_operator_retract_acquisition_channel(%L, %L, 'Article removed')$$,
                       tests.id('a1'), (select v #>> '{}' from r where k = 'seo')),
  'the operator retracts a channel');
select throws_ok(format($$select public.sor_operator_retract_acquisition_channel(%L, %L, 'again')$$,
                        tests.id('a1'), (select v #>> '{}' from r where k = 'seo')),
  '55000', null, 'a retracted channel cannot be retracted twice');
select tests.authenticate_as(tests.id('a4'));
select ok(not private.catalog_channel_matches(tests.id('d1'), '{"values":["seo"],"statuses":[],"include_unknown":false}'),
  'a retracted channel no longer matches the filter');

-- ------------------------------------------------------------ visuals: refusals
select tests.as_service_role();
select throws_ok($$select public.sor_admit_visual_asset(tests.id('a1'), tests.id('d1'),
    tests.asset('{"covers_private_copy":false}'), tests.png())$$,
  '22023', null, 'nothing is stored when the rights do not cover a private copy');
select throws_ok($$select public.sor_admit_visual_asset(tests.id('a1'), tests.id('d1'),
    tests.asset('{"rights_evidence_url":null}'), tests.png())$$,
  '22023', null, 'nothing is stored without evidence of the rights');
select throws_ok($$select public.sor_admit_visual_asset(tests.id('a1'), tests.id('d1'),
    tests.asset('{"content_type":"image/svg+xml"}'), tests.png())$$,
  '22023', null, 'SVG and other formats are refused');
select throws_ok($$select public.sor_admit_visual_asset(tests.id('a3'), tests.id('d1'), tests.asset(), tests.png())$$,
  '42501', null, 'only a platform operator admits a visual');
select is((select count(*)::int from public.product_visual_asset_files), 0, 'no private copy after refusals');

-- ------------------------------------------------------------ visuals: admit
insert into r values ('asset', public.sor_admit_visual_asset(tests.id('a1'), tests.id('d1'), tests.asset(), tests.png()));
select is((select v ->> 'status' from r where k = 'asset'), 'created', 'an authorised visual is admitted');
select is(public.sor_admit_visual_asset(tests.id('a1'), tests.id('d1'), tests.asset(), tests.png()) ->> 'asset_id',
          (select v ->> 'asset_id' from r where k = 'asset'), 'a replayed admission returns the same asset');
select is((select a.content_hash = encode(sha256(tests.png()), 'hex') and f.byte_size = octet_length(tests.png())
             from public.product_visual_assets a join public.product_visual_asset_files f on f.asset_id = a.id
            where a.id = (select (v ->> 'asset_id')::uuid from r where k = 'asset')), true,
  'the private copy and its hash are stored server-side');
select tests.authenticate_as(tests.id('a4'));
select is((select visual_asset ->> 'url' from public.catalog_discover_metadata(array[tests.id('d1')])),
  '/api/v1/catalog/assets/' || (select v ->> 'asset_id' from r where k = 'asset'),
  'Discover gets the authenticated delivery path, never the source URL to hotlink');
select is((select (visual_asset ->> 'width') || 'x' || (visual_asset ->> 'height')
             from public.catalog_discover_metadata(array[tests.id('d1')])), '1600x700',
  'the visual carries its dimensions');
select is((select count(*)::int from public.product_visual_assets
            where id = (select (v ->> 'asset_id')::uuid from r where k = 'asset')), 1,
  'a member reads the approved asset row (RLS)');

-- ------------------------------------------------------------ visuals: removal
select tests.as_service_role();
select lives_ok(format($$select public.sor_operator_remove_visual_asset(%L, %L, 'Takedown request')$$,
                       tests.id('a1'), (select v ->> 'asset_id' from r where k = 'asset')),
  'the operator removes a visual');
select is((select count(*)::int from public.product_visual_asset_files), 0, 'removal deletes the private copy');
select tests.authenticate_as(tests.id('a4'));
select is((select visual_asset from public.catalog_discover_metadata(array[tests.id('d1')])), null,
  'a removed visual disappears from Discover at once');
select is((select count(*)::int from public.product_visual_assets
            where id = (select (v ->> 'asset_id')::uuid from r where k = 'asset')), 0,
  'a removed asset row is no longer readable by members');

-- ------------------------------------------------------------ visuals: revalidation
select tests.as_service_role();
insert into r values ('asset2', public.sor_admit_visual_asset(tests.id('a1'), tests.id('d1'), tests.asset(), tests.png()));
select is(public.sor_record_visual_asset_check((select (v ->> 'asset_id')::uuid from r where k = 'asset2'),
            'unchanged', encode(sha256(tests.png()), 'hex')), 'unchanged',
  'an unchanged source keeps the visual');
select is(public.sor_record_visual_asset_check((select (v ->> 'asset_id')::uuid from r where k = 'asset2'),
            'unchanged', repeat('c', 64)), 'changed',
  'a different hash is recorded as changed');
select is((select count(*)::int from public.product_visual_asset_files), 0,
  'a changed source hides the visual and deletes its copy');
select is((select count(*)::int from public.audit_logs where action in
            ('catalog.acquisition_channel_recorded','catalog.acquisition_channel_retracted',
             'catalog.visual_asset_admitted','catalog.visual_asset_removed','catalog.visual_asset_checked')), 9,
  'every recording, retraction, admission, removal and check is audited');

-- ------------------------------------------------------------ least_analyzed
insert into public.saas_products (id, name, slug, record_status, exclusion_status, first_discovered_at)
  values (tests.id('d9a'), 'Product Nine', 'product-nine', 'active', 'eligible', now() - interval '30 days');
insert into public.opportunity_analyses (id, workspace_id, created_by, subject_type, subject_product_id,
                                         subject_snapshot, analysis_version, scoring_rules_version)
  values (tests.id('9a1'), tests.id('b1'), tests.id('a1'), 'product', tests.id('d1'), '{}', 'test', 'test');
insert into public.analysis_subject_products (analysis_id, product_id, role)
  values (tests.id('9a1'), tests.id('d1'), 'subject');
select tests.authenticate_as(tests.id('a4'));
select is((select array_agg(name order by ord) from (
             select name, row_number() over () as ord from public.catalog_search_v2(
               tests.id('b1'), '{"include_hidden":false,"configurable_exclusions":[]}', 'least_analyzed', 0, null, null, 10)) x),
  array['Product Nine', 'Product One'],
  'least_analyzed puts never-analysed products before analysed ones');
select throws_ok($$select * from public.catalog_search_v2(tests.id('b1'), '{}', 'ai_potential', 0, null, null, 10)$$,
  '22023', null, 'ai_potential stays unavailable (no real scores to sort by)');

select * from finish();
rollback;
